/** Extract plugin block definitions from the manifest for the Portable Text editor. */
function getPluginBlocks(manifest) {
	const blocks = [];
	for (const [pluginId, plugin] of Object.entries(manifest.plugins)) if (plugin.portableTextBlocks) for (const block of plugin.portableTextBlocks) blocks.push({
		...block,
		pluginId
	});
	return blocks;
}

